"""Unit tests for the fraction question model and factory."""

import unittest
from fractions import Fraction

from spacefractions.question.factory import default_questions
from spacefractions.question.models import Question, QuestionType, fraction_to_text


class FractionTextTests(unittest.TestCase):
    def test_whole_number(self):
        self.assertEqual(fraction_to_text(Fraction(6, 2)), "3")

    def test_fraction(self):
        self.assertEqual(fraction_to_text(Fraction(1, 2)), "1/2")


class QuestionModelTests(unittest.TestCase):
    def test_is_correct_ignores_whitespace(self):
        question = Question(id=1, prompt="p", options=("1/2", "3/4"), correct_answer="1/2", question_type=QuestionType.SIMPLIFY)
        self.assertTrue(question.is_correct(" 1/2 "))
        self.assertFalse(question.is_correct("3/4"))

    def test_default_questions_have_correct_option(self):
        for question in default_questions():
            self.assertIn(question.correct_answer, question.options)
            self.assertGreaterEqual(len(question.options), 3)


if __name__ == "__main__":
    unittest.main()
